INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community workers share experiences at SICAP consultations', 'sicap-consultations-pobal', '<p>In October, <em>Changing Ireland</em> heard about the ups and downs in the implementation of the Social Inclusion and Community Activation Programme (SICAP). Mostly ups.</p>
<p>Views were aired by community workers at a series of 17 meetings held around the country during the autumn. <a href="https://pobal.ie" target="_blank" rel="noopener noreferrer">Pobal</a> organised the meetings, which drew in hundreds of frontline workers and those overseeing SICAP at local level. The aim was to see what is working best and how to improve the programme.</p>
<p>There is no shortage of case studies to show the programme works and that it is reaching more community groups than ever before. The statistics bear this out. Statistics also show, however, that Travellers should be getting more support through the programme. Contradictions such as this clearly show why speaking to those on the front line is so important.</p>
<p>On that front line, complaints about the quantity of paperwork involved continue to be aired by community workers.</p>
<p>It was also pointed out that asking people if they have a criminal record before you begin working with them immediately puts up a barrier. Community workers felt this obligation compromised them.</p>
<h4><strong>Welcome consultations</strong></h4>
<p>The fact that community workers and others have been consulted was welcomed.</p>
<p>In discussions, it was agreed that not enough people in communities have heard of the SICAP programme, including the people who directly benefit from it.</p>
<p>A participant said: “We are hopeless at explaining what SICAP is trying to do.”</p>
<p>Another said: “You could spend time with a beneficiary, but at the end they still wouldn’t know it was through SICAP.”</p>
<p>“Our number-one audience is our community,” one community worker pointed out.</p>
<p>Colleagues made the following points:</p>
<p>&#8211; We need to link individuals’ stories to the policies that affect them, as Oxfam do.</p>
<p>&#8211; The testimony from people who have benefitted is what matters.</p>
<p>&#8211; The programme is backed up by community development principles, but that is not appreciated.</p>
<p>&#8211; We need to get people on the ground saying what they feel the programme is good for.</p>
<p>&#8211; People don’t relate to SICAP the acronym. The name is even a barrier.</p>
<p>Discussion followed about rebranding SICAP, or even renaming it.</p>
<p>The last of the 17 workshops in the series took place in Mayo on 25 October. These consultations were carried out in coordination with staff from the <a href="https://drcd.gov.ie" target="_blank" rel="noopener noreferrer">Department of Rural and Community Development</a>.</p>
<p>Between now and 2022, the SICAP programme will be worth €190m to communities.</p>', 'At a series of consultations that sought frontline views of SICAP, case studies and stories gave us a detailed picture.', 'https://changingireland.ie/wp-content/uploads/2019/09/Majella-OConnor-Limerick-City-Community-Development-watches-as-Mary-Blackmore-a-community-worker-with-the-PAUL-Partnership-gets-animated-over-SICAP-e1567510026105.jpg', 'Majella O''Connor of Limerick City Community Development, and Mary Blackmore of Paul Partnership', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"community-workers","title":"community workers"},{"slug":"consultations","title":"consultations"},{"slug":"sicap-social-inclusion-community-activation-programme","title":"SICAP"}]', '', 247618, 1, '2019-02-05T11:18:45Z', '2019-09-13T14:06:50Z', '2019-02-05T11:18:45Z')
