INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('WCDC: Bernadette on target, but Jim hits the bullseye', 'wcdc-2018-bernadette-jim-editorial', '<p>I first met Bernadette McAliskey in the mid-1990s, when it was hard work being a community activist in Co Tyrone.</p>
<p>I was a reporter with the <em>Mid-Ulster Mail</em>, and happened to be present for a small piece of history: President Mary Robinson dropped in on a community project in Coalisland, Co Tyrone, and was greeted on arrival by McAliskey.</p>
<p>The President was not on an official visit to the North. She came unofficially, to the annoyance of many and the joy of many more. She was paving the way for peace in a pushy way. An activist at heart.</p>
<p>Both women were on stage at the World Community Development Conference (WCDC) this summer, held in Maynooth, Co Kildare, in June.</p>
<p>McAliskey pointed to people involved in community work and asked what we are doing, if anything, about the rise of the super-rich and about inequality.</p>
<p>Jim Ife, later, went further. We’re so focused in community development on ourselves – meaning the activity of human beings – that we forget about nature and the environment. We’re missing the point of community development, he says.</p>
<p>The conference was a gathering of the faithful, though it would have cost you. Next year’s WCDC will be taking place in Dundee. Ask your company or organisation to part or fully fund your attendance.</p>
<p>Like the general Irish public with the Ploughing, every community worker should strive to go to at least one World Community Development Conference in their life.</p>
<p><em><a href="https://unsplash.com/photos/mX0987sQP8E" target="_blank" rel="noopener noreferrer">Main photo</a>: <a href="https://unsplash.com/@armoredsaint" target="_blank" rel="noopener noreferrer">Pablò</a>/<a href="https://unsplash.com/" target="_blank" rel="noopener noreferrer">Unsplash</a></em></p>', 'Following this summer’s World Community Development Conference, editor Allen Meagher reminisces about as past encounter with two of the headline speakers.', 'https://changingireland.ie/wp-content/uploads/2019/11/pablo-mX0987sQP8E-unsplash.jpg', 'Dartboard', '[{"slug":"development-work","title":"Development Work"}]', '[{"slug":"editorial","title":"Editorial"},{"slug":"events","title":"events"},{"slug":"history","title":"history"},{"slug":"opinion","title":"Opinion"},{"slug":"politics-and-elections","title":"politics and elections"}]', '', 248721, 1, '2018-11-05T13:04:23Z', '2019-11-08T13:39:18Z', '2018-11-05T13:04:23Z')
