INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('330 libraries to become ‘community hubs’ under new strategy', 'new-library-strategy-2020', '<p>A new five-year strategic policy document re-imagines the country’s 330 libraries as “community hubs”, open from early until late, 365 days of the year. As well as this, fines will soon be a thing of the past, according to ‘<a href="https://www.librariesireland.ie/sites/default/files/media/file-uploads/2018-12/LGMA-Our-Public-Libraries-2022-ENG.pdf" target="_blank" rel="noopener noreferrer">Our Public Libraries 2022 – Inspiring, Connecting and Empowering Communities</a>’.</p>
<p>There’s nothing like real consultation, and the new strategy has all-round backing. It was launched, with immaculate timing, a day after unions voted overwhelmingly to call off the threat of industrial action.</p>
<p>The new strategy was launched in the spectacular <a href="https://libraries.dlrcoco.ie/using-your-library/find-your-library/dlr-lexicon" target="_blank" rel="noopener noreferrer">LexIcon</a> in Dún Laoghaire by Minister for Rural and Community Development Michael Ring.</p>
<p>He said: “The overall aim is to increase active library membership from 16% of the population to 30% by the end of 2022.”</p>
<p>Judging by the <a href="https://www.cso.ie/en/census/census2016reports/" target="_blank" rel="noopener noreferrer">2016 census figures</a>, that means moving membership numbers up from 761,000 people to approximately 1,500,000 members by January 2023.</p>
<p>In part, that will be achieved by ending fines, extending opening hours, and reaching out further into communities.</p>
<p>On ending fines, Minister Ring said the strategy focuses on “removing barriers to access by eliminating fines and other charges and challenging the belief that the library is only for certain sectors of society.”</p>
<p>Fines are already gone in many areas and are on the way out in others.</p>
<p>The roll out of the My Open Library service will see a pilot scheme expanded to &#8220;up to 100 libraries by 2023, with the goal of reaching 200 library branches over the next decade”.</p>
<p>This means that libraries will be open at night-time, including over weekends.</p>
<p>The Minister said the strategy “aims to improve access, use and visibility of the library as a community hub, and develop the library as a focal point for community and cultural development”.</p>
<p>It promises to see our libraries “work with local partners to reach disadvantaged, marginalised and new communities, increasing these communities’ awareness of services available and firmly establishing the library as a resource for all”.</p>
<p>The five-year strategy is a joint initiative of the <a href="http://drcd.gov.ie" target="_blank" rel="noopener noreferrer">Department of Rural and Community Development</a>, the <a href="https://www.lgma.ie/en/ccma" target="_blank" rel="noopener noreferrer">County and City Management Association</a>, and the <a href="https://www.lgma.ie/en/" target="_blank" rel="noopener noreferrer">Local Government Management Agency</a>.</p>
<p>In the past 12 months, there has been a multimillion-euro increase in funding for our public library service, with the government investing more in libraries last year than in the three previous years combined.</p>
<p>Speaking at the time, Minister Ring said: “This very significant investment in our public libraries will enable the purchase of self-service technology for more than 200 libraries, books to promote literacy for children, and hot desk facilities for business people and jobseekers. It is an exciting time for the public library service and for library staff.”</p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our <a href="https://changingireland.ie/digital-magazine-archive/">latest issue</a>.</em></strong></p>', 'As Minister Michael Ring launches the new library strategy, we learn more about what the library of the future might look like.', 'https://changingireland.ie/wp-content/uploads/2020/01/IMG_8337-copy-scaled.jpg', 'Minister Ring reads to children in DLR LexIcon', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"community-facilities","title":"community facilities"},{"slug":"dublin","title":"Dublin"},{"slug":"michael-ring","title":"Michael Ring"},{"slug":"policy","title":"policy"},{"slug":"support-services","title":"support services"}]', '', 248771, 1, '2018-10-30T12:22:06Z', '2020-01-21T13:35:56Z', '2018-10-30T12:22:06Z')
