INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('How has the DEASP responded to recent JobPath criticism?', 'jobpath-criticism-deasp-response', '<p>Before we published Ben Panter’s article <a href="https://changingireland.ie/index.php/2017/12/17/jobpath-experience-report/" target="_blank" rel="noopener noreferrer">describing his experiences on JobPath</a>, we sent it to the <a href="https://welfare.ie" target="_blank" rel="noopener noreferrer">Department of Employment Affairs and Social Protection</a> (DEASP) – a recent name change for the Department of Social Protection – for comment.</p>
<p>Given the opportunity to respond to the article, the DEASP provided the following information:</p>
<p>The most recent performance report on the <a href="https://www.welfare.ie/en/Pages/JobPath.aspx" target="_blank" rel="noopener noreferrer">JobPath</a> service, published on the <a href="https://www.welfare.ie/" target="_blank" rel="noopener noreferrer">DEASP’s website</a>, indicates that 19% of jobseekers who engaged with JobPath between July 2015 and March 2016 entered full-time employment. This was 36% above the weighted reference performance rate of 14%.</p>
<p>Up to 31 October 2017, of the approximately 129,000 clients who had commenced with the service, 412 complaints have been made, representing 0.32% of the total number who have engaged.</p>
<p>The department commissioned a customer satisfaction survey to be carried out at the end of 2016. The survey was conducted using a representative sample of 2,000 JobPath clients (1,000 from each provider).</p>
<p>The results of the survey indicated that jobseekers feel that they are receiving a good service, with 76% to 81% satisfaction, against 5% to 8% dissatisfaction; that the contractor’s staff make them feel valued (90%+); and that they have a good relationship with their personal adviser (90%+). They also feel that the service has improved their chances of getting a job (68% to 77%).</p>
<p>There is a robust complaints process and inspections regime in place for the oversight of the JobPath contracts. Should a customer feel they have received a less than satisfactory service; it is recommended that they engage with the complaints process provided.</p>
<p>During their time on JobPath, participants are encouraged and supported to take up employment-related training, upskilling or other activities that could lead to a sustainable job, in addition to assistance with the job application process.</p>
<p>If a person is successful in finding employment, the JobPath company will provide in-work support to assist with the move back into employment.</p>
<h4><strong>What is JobPath?</strong></h4>
<p>JobPath is described on <a href="https://www.welfare.ie/">welfare.ie</a> as “an employment activation service provided to assist jobseekers on the live register to secure and sustain full-time paid employment or self-employment”.  The service is provided on behalf of the Department by two private companies: <a href="https://www.seetec.ie/">Seetec</a> and <a href="https://www.turasnua.ie/">Turas Nua</a>.</p>
<p><strong>Who gets called?</strong></p>
<p>The department selects jobseekers on a random basis for referral to JobPath. The scheme is backed by sanctions for those who, without good cause, do not cooperate.</p>
<h4><strong>Success v criticism</strong></h4>
<p>There is no doubting the government’s success in reducing unemployment, from a high of 15% five years ago to 6% today. Nonetheless, long-term unemployment remains high and the JobPath scheme – while well-meaning, and in spite of the government saying that the number of formal complaints is low – has drawn much criticism.</p>
<p>Opposition parties say JobPath makes it impossible for people to take up internships or CE places, to the detriment of communities depending on CE-supported services.</p>
<p><a href="https://www.socialdemocrats.ie/">Social Democrats</a> TD Catherine Murphy has raised very serious complaints about the scheme in the Dáil. <a href="https://www.sinnfein.ie" target="_blank" rel="noopener noreferrer">Sinn Féin</a> said JobPath sometimes makes it harder for unemployed people to find work and has published a document called ‘<a href="https://www.sinnfein.ie/files/2018/JobPath_Report_SF.pdf">JobPath Exposed</a>’. Fianna Fáil labour spokesperson Willie O’Dea has highlighted the intrusiveness of questions posed by Turas Nua.</p>
<p>Citizens have also challenged the demand on them to “comply and engage”.</p>', 'Amid criticism and concerns about the JobPath programme, the recently rebranded Department of Employment Affairs and Social Protection has touted its successes.', 'https://changingireland.ie/wp-content/uploads/2017/12/Screenshot-2019-08-01-at-12.10.15.png', 'Regina Doherty speaks at SIF 2019', '[{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"department-employment-affairs-social-protection-deasp-welfare","title":"Department of Employment Affairs and Social Protection"},{"slug":"employment-supports","title":"employment supports"},{"slug":"government","title":"government"},{"slug":"jobpath","title":"JobPath"},{"slug":"jobseekers","title":"jobseekers"},{"slug":"reports","title":"reports"},{"slug":"sinn-fein","title":"Sinn Féin"},{"slug":"social-democrats","title":"Social Democrats"},{"slug":"unemployment","title":"unemployment"}]', '', 696, 1, '2017-12-18T10:05:54Z', '2019-09-13T14:27:49Z', '2017-12-18T10:05:54Z')
